/**
 * Node Help Panel + safe zero-dependency Markdown renderer.
 * Fetches live Markdown docs from /api/docs/{typeId}?lang=... (external-first + embedded fallback + auto-generated).
 */
const HelpPanel = {
  _catalog: [],
  _currentTypeId: null,
  _requestSeq: 0,

  init(catalog) {
    this.setCatalog(catalog);
    const sel = document.getElementById("help-node-select");
    const refreshBtn = document.getElementById("btn-help-refresh");

    if (sel) {
      sel.addEventListener("change", () => {
        if (sel.value) this.showNode(sel.value, false);
      });
    }
    if (refreshBtn) {
      refreshBtn.addEventListener("click", () => {
        if (this._currentTypeId) this.showNode(this._currentTypeId, false);
      });
    }
  },

  setCatalog(catalog) {
    this._catalog = Array.isArray(catalog) ? catalog : [];
    const sel = document.getElementById("help-node-select");
    if (!sel) return;

    const prev = this._currentTypeId || sel.value;
    sel.innerHTML = "";

    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = t("help.selectNode");
    sel.appendChild(placeholder);

    const byCat = new Map();
    for (const d of this._catalog) {
      if (!byCat.has(d.category)) byCat.set(d.category, []);
      byCat.get(d.category).push(d);
    }

    for (const [cat, items] of byCat) {
      const grp = document.createElement("optgroup");
      grp.label = cat;
      for (const d of items) {
        const opt = document.createElement("option");
        opt.value = d.typeId;
        opt.textContent = d.displayName;
        if (d.typeId === prev) opt.selected = true;
        grp.appendChild(opt);
      }
      sel.appendChild(grp);
    }

    if (this._currentTypeId) {
      this.showNode(this._currentTypeId, false);
    } else {
      this._renderEmpty();
    }
  },

  async showNode(typeId, switchTab = false) {
    if (switchTab && typeof activateRightTab === "function") {
      activateRightTab("help");
    }
    if (!typeId) {
      this._currentTypeId = null;
      this._renderEmpty();
      return;
    }

    this._currentTypeId = typeId;
    const sel = document.getElementById("help-node-select");
    if (sel && sel.value !== typeId) sel.value = typeId;

    const body = document.getElementById("help-body");
    if (!body) return;

    const seq = ++this._requestSeq;
    body.innerHTML = `<div class="debug-empty">${t("help.loading")}</div>`;

    try {
      const doc = await Api.getNodeDocs(typeId, currentLang);
      if (seq !== this._requestSeq) return;
      if (!doc) {
        body.innerHTML = `<div class="debug-empty">${t("help.empty")}</div>`;
        return;
      }

      const badges = [];
      badges.push(`<span class="help-badge">${this._escapeHtml(doc.category || "")}</span>`);
      badges.push(`<span class="help-badge is-mono">${this._escapeHtml(doc.typeId)}</span>`);
      if (doc.isAutoGenerated) {
        badges.push(`<span class="help-badge is-warn">${this._escapeHtml(t("help.autoGenerated"))}</span>`);
      } else if (doc.isFallback) {
        badges.push(`<span class="help-badge is-warn">${this._escapeHtml(t("help.fallback"))} (${this._escapeHtml((doc.resolvedLang || "en").toUpperCase())})</span>`);
      } else {
        badges.push(`<span class="help-badge is-ok">${this._escapeHtml((doc.resolvedLang || "en").toUpperCase())}</span>`);
      }

      body.innerHTML = `
        <div class="help-meta-row">${badges.join("")}</div>
        <article class="help-md">${this.renderMarkdown(doc.markdown || "")}</article>
      `;
    } catch {
      if (seq !== this._requestSeq) return;
      body.innerHTML = `<div class="debug-empty">${t("help.empty")}</div>`;
    }
  },

  _renderEmpty() {
    const body = document.getElementById("help-body");
    if (body) {
      body.innerHTML = `<div class="debug-empty">${t("help.empty")}</div>`;
    }
  },

  _escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  },

  _renderInline(raw) {
    let s = this._escapeHtml(raw);
    // Inline code spans first (protect contents from bold/italic processing)
    const codeSlots = [];
    s = s.replace(/`([^`]+)`/g, (_, code) => {
      const idx = codeSlots.length;
      codeSlots.push(`<code>${code}</code>`);
      return `\u0000CODE${idx}\u0000`;
    });

    // Links: only allow http(s) or # anchors
    s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, href) => {
      const safeHref = href.trim();
      if (/^(https?:\/\/|#)/i.test(safeHref)) {
        return `<a href="${safeHref}" target="_blank" rel="noopener noreferrer">${label}</a>`;
      }
      return label;
    });

    // Bold & italic
    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/(^|[^*])\*([^*]+)\*(?!\*)/g, "$1<em>$2</em>");

    // Restore code spans
    s = s.replace(/\u0000CODE(\d+)\u0000/g, (_, idx) => codeSlots[Number(idx)] || "");
    return s;
  },

  renderMarkdown(md) {
    const lines = String(md || "").replace(/\r\n/g, "\n").split("\n");
    const out = [];
    let i = 0;

    while (i < lines.length) {
      const line = lines[i];

      // Blank line
      if (!line.trim()) {
        i++;
        continue;
      }

      // Fenced code block
      const fence = line.match(/^```(\w*)\s*$/);
      if (fence) {
        const lang = fence[1] || "";
        const buf = [];
        i++;
        while (i < lines.length && !/^```\s*$/.test(lines[i])) {
          buf.push(lines[i]);
          i++;
        }
        i++; // skip closing fence
        out.push(`<pre class="md-pre"><code${lang ? ` class="lang-${this._escapeHtml(lang)}"` : ""}>${this._escapeHtml(buf.join("\n"))}</code></pre>`);
        continue;
      }

      // Headings
      const h = line.match(/^(#{1,4})\s+(.+)$/);
      if (h) {
        const lvl = h[1].length;
        out.push(`<h${lvl}>${this._renderInline(h[2].trim())}</h${lvl}>`);
        i++;
        continue;
      }

      // Horizontal rule
      if (/^\s*([-*_])\1{2,}\s*$/.test(line)) {
        out.push("<hr />");
        i++;
        continue;
      }

      // Blockquote
      if (/^\s*>\s?/.test(line)) {
        const qLines = [];
        while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
          qLines.push(lines[i].replace(/^\s*>\s?/, ""));
          i++;
        }
        out.push(`<blockquote>${qLines.map((l) => this._renderInline(l)).join("<br />")}</blockquote>`);
        continue;
      }

      // Pipe table
      if (line.includes("|") && i + 1 < lines.length && /^\s*\|?(\s*:?-{3,}:?\s*\|)+\s*:?-{3,}:?\s*\|?\s*$/.test(lines[i + 1])) {
        const parseRow = (rowStr) =>
          rowStr.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((c) => c.trim());
        const headers = parseRow(line);
        i += 2; // skip header + separator
        const rows = [];
        while (i < lines.length && lines[i].includes("|") && lines[i].trim()) {
          rows.push(parseRow(lines[i]));
          i++;
        }
        const ths = headers.map((c) => `<th>${this._renderInline(c)}</th>`).join("");
        const trs = rows.map((r) => `<tr>${r.map((c) => `<td>${this._renderInline(c)}</td>`).join("")}</tr>`).join("");
        out.push(`<div class="md-table-wrap"><table class="md-table"><thead><tr>${ths}</tr></thead><tbody>${trs}</tbody></table></div>`);
        continue;
      }

      // Unordered list
      if (/^\s*[-*]\s+/.test(line)) {
        const items = [];
        while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
          items.push(`<li>${this._renderInline(lines[i].replace(/^\s*[-*]\s+/, ""))}</li>`);
          i++;
        }
        out.push(`<ul>${items.join("")}</ul>`);
        continue;
      }

      // Ordered list
      if (/^\s*\d+\.\s+/.test(line)) {
        const items = [];
        while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
          items.push(`<li>${this._renderInline(lines[i].replace(/^\s*\d+\.\s+/, ""))}</li>`);
          i++;
        }
        out.push(`<ol>${items.join("")}</ol>`);
        continue;
      }

      // Paragraph
      const pLines = [];
      while (
        i < lines.length &&
        lines[i].trim() &&
        !/^(#{1,4}\s|```|\s*>\s?|\s*[-*]\s+|\s*\d+\.\s+|\s*([-*_])\1{2,}\s*$)/.test(lines[i])
      ) {
        pLines.push(lines[i].trim());
        i++;
      }
      out.push(`<p>${this._renderInline(pLines.join(" "))}</p>`);
    }

    return out.join("\n");
  },
};
